package com.oneonone;

import java.util.*;
import java.util.stream.Stream;

/**
 * The question bank: 1on1's own problems first, then external question metadata (titles and links only, never
 * statements) generated by scripts/import_questions.py from Codeforces' API and an MIT LeetCode company dataset.
 */
@org.springframework.stereotype.Service
public class BankService {

  final Store store;
  private volatile List<Map<String, Object>> external;

  public BankService(Store store) {
    this.store = store;
  }

  @SuppressWarnings("unchecked")
  List<Map<String, Object>> external() {
    if (external == null) synchronized (this) {
      if (external == null) try (var in = getClass().getResourceAsStream("/external-questions.json")) {
        external = List.copyOf((List<Map<String, Object>>) (List<?>) store.json.readValue(in, List.class));
      } catch (java.io.IOException e) {
        throw new IllegalStateException("The question bank file is missing; run scripts/import_questions.py.", e);
      }
    }
    return external;
  }

  private volatile List<Map<String, Object>> ownCache;
  private volatile long ownLoadedAt;

  List<Map<String, Object>> own() {
    // shortcut: a 60 s cache, so an admin's edit appears within a minute; invalidate on save if that matters
    if (ownCache == null || System.currentTimeMillis() - ownLoadedAt > 60_000) {
      ownCache = loadOwn();
      ownLoadedAt = System.currentTimeMillis();
    }
    return ownCache;
  }

  List<Map<String, Object>> loadOwn() {
    return store.list("problem", "public").stream()
      .filter(p -> !Boolean.FALSE.equals(p.get("published")))
      .sorted(Comparator.comparingInt(p -> ((Number) p.getOrDefault("order", 999)).intValue()))
      .map(p -> {
        var r = new LinkedHashMap<String, Object>();
        r.put("id", p.get("id"));
        r.put("source", "1on1");
        r.put("title", p.get("title"));
        r.put("url", "/practice/" + p.get("id"));
        r.put("difficulty", p.get("difficulty"));
        r.put("tags", Store.strings(p.get("topics")));
        r.put("rating", null);
        r.put("companies", Map.of());
        return (Map<String, Object>) r;
      })
      .toList();
  }

  static boolean has(String filter) {
    return filter != null && !filter.isBlank();
  }

  static int companyCount(Map<String, Object> r, String company) {
    if (!(r.get("companies") instanceof Map<?, ?> m)) return 0;
    for (var e : m.entrySet()) if (e.getKey().toString().equalsIgnoreCase(company) && e.getValue() instanceof Number n) return n.intValue();
    return 0;
  }

  public Map<String, Object> search(String q, String source, String difficulty, String topic, String company, int page, int size) {
    int pageSize = Math.max(1, Math.min(100, size));
    String needle = has(q) ? q.strip().toLowerCase(Locale.ROOT) : "";
    var rows = Stream.concat(own().stream(), external().stream())
      .filter(r -> needle.isEmpty() || r.get("title").toString().toLowerCase(Locale.ROOT).contains(needle))
      .filter(r -> !has(source) || source.equalsIgnoreCase(String.valueOf(r.get("source"))))
      .filter(r -> !has(difficulty) || difficulty.equalsIgnoreCase(String.valueOf(r.get("difficulty"))))
      .filter(r -> !has(topic) || Store.strings(r.get("tags")).stream().anyMatch(topic::equalsIgnoreCase))
      .filter(r -> !has(company) || companyCount(r, company) > 0);
    if (has(company)) rows = rows.sorted(Comparator.comparingInt((Map<String, Object> r) -> companyCount(r, company)).reversed());
    var all = rows.toList();
    int from = (int) Math.min((long) Math.max(0, page) * pageSize, all.size());
    var out = new LinkedHashMap<String, Object>();
    out.put("items", all.subList(from, Math.min(all.size(), from + pageSize)));
    out.put("total", all.size());
    out.put("page", Math.max(0, page));
    out.put("size", pageSize);
    return out;
  }

  public List<Map<String, Object>> companies() {
    Map<String, Integer> counts = new HashMap<>();
    for (var r : external()) if (r.get("companies") instanceof Map<?, ?> m) for (Object name : m.keySet()) counts.merge(name.toString(), 1, Integer::sum);
    return counts.entrySet().stream()
      .sorted(Map.Entry.<String, Integer>comparingByValue().reversed().thenComparing(Map.Entry.comparingByKey()))
      .map(e -> Map.<String, Object>of("name", e.getKey(), "count", e.getValue()))
      .toList();
  }

  /** Every tag in the bank, 1on1 topics first, for the topic filter. */
  public List<String> topics() {
    var out = new LinkedHashSet<String>();
    for (var r : own()) out.addAll(Store.strings(r.get("tags")));
    var external = new TreeSet<String>();
    for (var r : external()) external.addAll(Store.strings(r.get("tags")));
    out.addAll(external);
    return List.copyOf(out);
  }

  /** How many of a company's reported questions are Easy, Medium and Hard; the mock OA mirrors this mix. */
  public Map<String, Long> difficultyMix(String company) {
    Map<String, Long> mix = new LinkedHashMap<>();
    for (var r : external()) if (companyCount(r, company) > 0 && r.get("difficulty") != null) mix.merge(r.get("difficulty").toString(), 1L, Long::sum);
    return mix;
  }
}
